
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_regtm_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_regtm", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.654173529106942e+00, -4.561506326025194e+00, -4.431724482315455e+00, -4.252087479634047e+00, -4.007616073704401e+00, -3.682904774038141e+00, -3.266382104052953e+00, -2.757844420158386e+00, -2.177571707261295e+00, -1.568432703513199e+00, -1.011390667562391e+00, -7.094446393143617e-01, -5.997931690734312e-01, -5.099426684962644e-01, -3.666832395535609e-01, -2.263412018240496e-01, -1.198042122474565e-01, -5.402436563089785e-02, -2.012346727084225e-02, -5.340788263075082e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


